-- Runs every data quality test of one layer, logs the failure
-- counts to ops.DataQualityResult and raises an error when an
-- error-severity test fails, which stops the job (stale but right
-- beats fresh but wrong).
-- Generated by `python -m dbde render` from every spec under models/. Do not edit: change the spec and render again.

CREATE OR REPLACE PROCEDURE ${gold_catalog}.ops.RunDataQualityTests(
    TestLayer STRING,
    RunLoadStepID STRING
)
LANGUAGE SQL
SQL SECURITY INVOKER
COMMENT 'Runs the data quality tests of one layer. Generated by dbde.'
AS BEGIN
    DECLARE FailedTests BIGINT DEFAULT 0;
    DECLARE FailureMessage STRING DEFAULT '';

    IF TestLayer = 'source' THEN
        -- policy_admin.policy: freshness_warn___ingested_at
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'source', 'policy_admin.policy', 'freshness_warn___ingested_at',
            'warn', count(*), current_timestamp()
        FROM (select latest from (select max(`_ingested_at`) as latest from ${bronze_catalog}.policy_admin.policy) as newest where latest is null or timestampdiff(HOUR, latest, current_timestamp()) > 26) AS failing;
        -- policy_admin.policy: freshness_error___ingested_at
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'source', 'policy_admin.policy', 'freshness_error___ingested_at',
            'error', count(*), current_timestamp()
        FROM (select latest from (select max(`_ingested_at`) as latest from ${bronze_catalog}.policy_admin.policy) as newest where latest is null or timestampdiff(HOUR, latest, current_timestamp()) > 48) AS failing;
        -- policy_admin.agent: freshness_warn___ingested_at
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'source', 'policy_admin.agent', 'freshness_warn___ingested_at',
            'warn', count(*), current_timestamp()
        FROM (select latest from (select max(`_ingested_at`) as latest from ${bronze_catalog}.policy_admin.agent) as newest where latest is null or timestampdiff(HOUR, latest, current_timestamp()) > 26) AS failing;
        -- policy_admin.agent: freshness_error___ingested_at
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'source', 'policy_admin.agent', 'freshness_error___ingested_at',
            'error', count(*), current_timestamp()
        FROM (select latest from (select max(`_ingested_at`) as latest from ${bronze_catalog}.policy_admin.agent) as newest where latest is null or timestampdiff(HOUR, latest, current_timestamp()) > 48) AS failing;
    END IF;

    IF TestLayer = 'silver' THEN
        -- policy_admin.Agent: not_null__Agent_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Agent', 'not_null__Agent_BK',
            'error', count(*), current_timestamp()
        FROM (select `Agent_BK` from ${silver_catalog}.policy_admin.Agent where `Agent_BK` is null) AS failing;
        -- policy_admin.Agent: unique__Agent_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Agent', 'unique__Agent_BK',
            'error', count(*), current_timestamp()
        FROM (select `Agent_BK` from ${silver_catalog}.policy_admin.Agent where `Agent_BK` is not null group by `Agent_BK` having count(*) > 1) AS failing;
        -- policy_admin.Policy: not_null__Policy_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Policy', 'not_null__Policy_BK',
            'error', count(*), current_timestamp()
        FROM (select `Policy_BK` from ${silver_catalog}.policy_admin.Policy where `Policy_BK` is null) AS failing;
        -- policy_admin.Policy: unique__Policy_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Policy', 'unique__Policy_BK',
            'error', count(*), current_timestamp()
        FROM (select `Policy_BK` from ${silver_catalog}.policy_admin.Policy where `Policy_BK` is not null group by `Policy_BK` having count(*) > 1) AS failing;
        -- policy_admin.Policy: accepted_values__PolicyStatusCode
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Policy', 'accepted_values__PolicyStatusCode',
            'error', count(*), current_timestamp()
        FROM (select `PolicyStatusCode` from ${silver_catalog}.policy_admin.Policy where `PolicyStatusCode` is not null and `PolicyStatusCode` not in ('IF', 'LA', 'UNKNOWN')) AS failing;
        -- policy_admin.Policy: accepted_range__AnnualPremiumAmount
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Policy', 'accepted_range__AnnualPremiumAmount',
            'error', count(*), current_timestamp()
        FROM (select `AnnualPremiumAmount` from ${silver_catalog}.policy_admin.Policy where `AnnualPremiumAmount` < 0) AS failing;
        -- policy_admin.Policy: expression__table_1
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'policy_admin.Policy', 'expression__table_1',
            'error', count(*), current_timestamp()
        FROM (select * from ${silver_catalog}.policy_admin.Policy where not (IssueDate is null or IssueDate >= ApplicationDate)) AS failing;
        -- sales.NewBusinessPolicy: not_null__Policy_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'sales.NewBusinessPolicy', 'not_null__Policy_BK',
            'error', count(*), current_timestamp()
        FROM (select `Policy_BK` from ${silver_catalog}.sales.NewBusinessPolicy where `Policy_BK` is null) AS failing;
        -- sales.NewBusinessPolicy: unique__Policy_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'silver', 'sales.NewBusinessPolicy', 'unique__Policy_BK',
            'error', count(*), current_timestamp()
        FROM (select `Policy_BK` from ${silver_catalog}.sales.NewBusinessPolicy where `Policy_BK` is not null group by `Policy_BK` having count(*) > 1) AS failing;
    END IF;

    IF TestLayer = 'gold' THEN
        -- distribution.DimAgent: not_null__Agent_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'distribution.DimAgent', 'not_null__Agent_BK',
            'error', count(*), current_timestamp()
        FROM (select `Agent_BK` from ${gold_catalog}.distribution.DimAgent where `Agent_BK` is null) AS failing;
        -- distribution.DimAgent: one_current_row__Agent_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'distribution.DimAgent', 'one_current_row__Agent_BK',
            'error', count(*), current_timestamp()
        FROM (select `Agent_BK` from ${gold_catalog}.distribution.DimAgent group by `Agent_BK` having count_if(`IsCurrent`) <> 1) AS failing;
        -- distribution.DimAgent: no_overlapping_versions__Agent_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'distribution.DimAgent', 'no_overlapping_versions__Agent_BK',
            'error', count(*), current_timestamp()
        FROM (select earlier.`DimAgent_SK` from ${gold_catalog}.distribution.DimAgent as earlier inner join ${gold_catalog}.distribution.DimAgent as later on earlier.`Agent_BK` = later.`Agent_BK` and earlier.`DimAgent_SK` < later.`DimAgent_SK` and earlier.`StartDate` <= later.`EndDate` and later.`StartDate` <= earlier.`EndDate`) AS failing;
        -- distribution.DimAgent: expression__table
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'distribution.DimAgent', 'expression__table',
            'error', count(*), current_timestamp()
        FROM (select * from ${gold_catalog}.distribution.DimAgent where not (StartDate <= EndDate)) AS failing;
        -- distribution.DimAgent: not_null__DimAgent_SK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'distribution.DimAgent', 'not_null__DimAgent_SK',
            'error', count(*), current_timestamp()
        FROM (select `DimAgent_SK` from ${gold_catalog}.distribution.DimAgent where `DimAgent_SK` is null) AS failing;
        -- distribution.DimAgent: unique__DimAgent_SK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'distribution.DimAgent', 'unique__DimAgent_SK',
            'error', count(*), current_timestamp()
        FROM (select `DimAgent_SK` from ${gold_catalog}.distribution.DimAgent where `DimAgent_SK` is not null group by `DimAgent_SK` having count(*) > 1) AS failing;
        -- sales.FactNewBusiness: not_null__Policy_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'not_null__Policy_BK',
            'error', count(*), current_timestamp()
        FROM (select `Policy_BK` from ${gold_catalog}.sales.FactNewBusiness where `Policy_BK` is null) AS failing;
        -- sales.FactNewBusiness: unique__Policy_BK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'unique__Policy_BK',
            'error', count(*), current_timestamp()
        FROM (select `Policy_BK` from ${gold_catalog}.sales.FactNewBusiness where `Policy_BK` is not null group by `Policy_BK` having count(*) > 1) AS failing;
        -- sales.FactNewBusiness: not_null__FactNewBusiness_SK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'not_null__FactNewBusiness_SK',
            'error', count(*), current_timestamp()
        FROM (select `FactNewBusiness_SK` from ${gold_catalog}.sales.FactNewBusiness where `FactNewBusiness_SK` is null) AS failing;
        -- sales.FactNewBusiness: unique__FactNewBusiness_SK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'unique__FactNewBusiness_SK',
            'error', count(*), current_timestamp()
        FROM (select `FactNewBusiness_SK` from ${gold_catalog}.sales.FactNewBusiness where `FactNewBusiness_SK` is not null group by `FactNewBusiness_SK` having count(*) > 1) AS failing;
        -- sales.FactNewBusiness: not_null__DimAgent_SK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'not_null__DimAgent_SK',
            'error', count(*), current_timestamp()
        FROM (select `DimAgent_SK` from ${gold_catalog}.sales.FactNewBusiness where `DimAgent_SK` is null) AS failing;
        -- sales.FactNewBusiness: relationships__DimAgent_SK
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'relationships__DimAgent_SK',
            'error', count(*), current_timestamp()
        FROM (select child.`DimAgent_SK` from ${gold_catalog}.sales.FactNewBusiness as child left join ${gold_catalog}.distribution.DimAgent as parent on child.`DimAgent_SK` = parent.`DimAgent_SK` where child.`DimAgent_SK` is not null and parent.`DimAgent_SK` is null) AS failing;
        -- sales.FactNewBusiness: accepted_range__AnnualPremiumAmount
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'accepted_range__AnnualPremiumAmount',
            'error', count(*), current_timestamp()
        FROM (select `AnnualPremiumAmount` from ${gold_catalog}.sales.FactNewBusiness where `AnnualPremiumAmount` < 0) AS failing;
        -- sales.FactNewBusiness: row_count_between__table_1
        INSERT INTO ${gold_catalog}.ops.DataQualityResult
        SELECT RunLoadStepID, 'gold', 'sales.FactNewBusiness', 'row_count_between__table_1',
            'warn', count(*), current_timestamp()
        FROM (select row_count from (select count(*) as row_count from ${gold_catalog}.sales.FactNewBusiness) as counted where row_count < 1) AS failing;
    END IF;

    SET FailedTests = (
        SELECT count(*) FROM ${gold_catalog}.ops.DataQualityResult
        WHERE LoadStepID = RunLoadStepID AND Layer = TestLayer
            AND Severity = 'error' AND FailureCount > 0
    );
    IF FailedTests > 0 THEN
        SET FailureMessage = concat(FailedTests, ' ', TestLayer,
            ' data quality test(s) failed. See',
            ' ops.DataQualityResult for LoadStepID ',
            RunLoadStepID, '.');
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = FailureMessage;
    END IF;
END;
-- GO
